-- Hand-written, not generated by `npm run db:schema:apply` (supabase/CLAUDE.md's declarative
-- sync tool silently omits CREATE STATISTICS objects from its diff — confirmed: running the
-- generator after adding this statement to supabase/schema/schemas/public/tables/"Sessions".sql
-- applied cleanly to the shadow database but produced no migration file and left the local
-- database unchanged). Mirrors exactly the statement declared in that schema file.
--
-- See that file's own comment for the full rationale: teaches the planner that
-- ringing_group_id and visit_date are correlated, fixing a cardinality misestimate that flips
-- Sessions' access path and collapses a ~12-row estimate to 1 when a query combines an exact
-- group filter with a fully-covering visit_date range.
CREATE STATISTICS public.sessions_ringing_group_id_visit_date_stats
  ON ringing_group_id, visit_date
  FROM public."Sessions";
